const all=[...new Map(stages.flatMap(s=>s.cards).map(c=>[c.id,c])).values()],modes=['ua','de','listen','write','speak'];let session=null,recognition=null,voiceRun=0;
const en=()=>document.documentElement.lang.startsWith('en'),t=(ua,english)=>en()?english:ua,meaning=c=>en()?c.en:c.ua;
const norm=s=>String(s).normalize('NFC').toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').replace(/[.!?,;:]/g,'').replace(/\s+/g,' ').trim();
const day=now=>{const d=new Date(now);return [d.getFullYear(),d.getMonth(),d.getDate()].join('-')};
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=kind=>uiGlyph({ua:'translateFrom',de:'translateTo',listen:'sound',write:'write',speak:'mic'}[kind]||kind);
const label=type=>({ua:t('Вибери переклад','Choose the translation'),de:t('Вибери німецькою','Choose in German'),listen:t('Послухай і вибери переклад','Listen and choose the translation'),write:t('Напиши німецькою','Write in German'),speak:t('Скажи німецькою','Say it in German')})[type];
function load(){const raw=profileStorage.getItem(key);if(!raw)return {version:1,cards:{},sessions:{},carouselMigrated:true};const d=JSON.parse(raw);if(d.version!==1||!d.cards)throw Error('Unsupported learning data');d.sessions=d.sessions||{};if(!d.carouselMigrated){for(const s of stages)if(s.cards.every(c=>!d.cards[c.id]?.skills&&(d.cards[c.id]?.success||0)>=3))d.sessions[s.id]={migrated:true,last:Date.now()};d.carouselMigrated=true;save(d)}return d}
function save(d){profileStorage.setItem(key,JSON.stringify(d))}
function ready(c,d){const x=d.cards[c.id];return x?.skills?modes.slice(0,4).every(type=>x.skills[type]?.step>=2):x?.step>=2}
function stageIndex(d){const i=stages.findIndex(s=>!d.sessions[s.id]&&!s.cards.every(c=>!d.cards[c.id]?.skills&&(d.cards[c.id]?.success||0)>=3));return i<0?stages.length:i}
function plan(now=Date.now()){const d=load(),n=stageIndex(d),available=stages.slice(0,Math.min(n+1,stages.length)).flatMap(s=>s.cards),due=all.filter(c=>d.cards[c.id]?.due<=now),selected=n<stages.length?[...stages[n].cards]:shuffle(all).slice(0,6);return {d,n,due,selected,fresh:selected.filter(c=>!d.cards[c.id]),newToday:Object.values(d.cards).filter(c=>c.introduced&&day(c.introduced)===day(now)).length}}
function art(c){const a=window.DEUTSCH_COURSE_ART;return a?.html(c.de,c.ua)||(c.visual?a?.html(...c.visual):'')||''}
function play(c){return speak(c.de)}
function shell(html){root.innerHTML='<div class="al-wrap">'+html+'</div>';root.querySelectorAll('[data-al-audio]').forEach(b=>b.onclick=()=>play(all.find(c=>c.id===b.dataset.alAudio)));root.querySelectorAll('[data-journey-greeting]').forEach(b=>b.onclick=()=>speak(b.dataset.journeyGreeting));const camp=root.querySelector('#campGreetings');if(camp)camp.onclick=()=>greetingsOpen(true);}
const listen=c=>`<button type="button" class="al-audio" data-al-audio="${esc(c.id)}" aria-label="${esc(t('Прослухати','Listen')+' '+c.de)}">${icon('listen')}</button>`;
function optionsFor(c){const own=stages.find(s=>s.cards.some(z=>z.id===c.id))?.cards||all,current=session?.batch||[],source=current.some(z=>z.id===c.id)&&current.filter(z=>z.group===c.group).length>1?current:own;const seen=new Set([meaning(c)]),pool=shuffle(source.filter(z=>z.group===c.group&&z.id!==c.id)).filter(z=>{if(seen.has(meaning(z)))return false;seen.add(meaning(z));return true});return shuffle([c,...pool.slice(0,3)])}
function lettersFor(c){const required=[...new Set(Array.from(c.de.normalize('NFC').toLowerCase().replace(/[.!?,;:]/g,'')))];const alphabet=Array.from('abcdefghijklmnopqrstuvwxyzäöüß'),confusing={d:'bt',u:'onü',i:'le',e:'äa',s:'zß',h:'nk',w:'vm',r:'np'};const candidates=shuffle([...required.flatMap(l=>Array.from(confusing[l]||'')),...shuffle(alphabet)]),extra=[];for(const l of candidates)if(!required.includes(l)&&!extra.includes(l)){extra.push(l);if(extra.length===8)break}return shuffle([...required,...extra])}
function stopVoice(){voiceRun++;if(recognition){recognition.onresult=null;recognition.onend=null;recognition.onerror=null;try{recognition.abort()}catch{}recognition=null}}
function pause(){stopVoice();window.DEUTSCH_FLOW?.pause()}
function cancel(){pause();session=null}
function legacyRender(){try{cancel();const p=plan();shell(`<div class="tag">${t('Твій темп · п’ять способів пригадати','Your pace · five ways to recall')}</div><h1>${t('Навчання','Learning')}</h1><section class="al-hero"><h2>${p.n<stages.length?stages[p.n].title[en()?1:0]:t('Закріплюємо знайоме','Reinforce familiar material')}</h2><p>${t('Порції по 4–6 слів або конструкцій. Переклад, вибір німецькою, слухання, письмо й мікрофон.','Batches of 4–6 words or patterns. Translation, German choices, listening, writing and microphone.')}</p><button class="btn primary" id="alStart">${t('Почати заняття','Start session')}</button></section><p class="study-note">${t('Денний орієнтир: 6 нових елементів. Сьогодні: ','Daily guide: 6 new items. Today: ')}${p.newToday}. ${t('Можна продовжувати без обмежень.','Continue without limits.')}</p><p>${t('Закріплено після перерви','Recalled after a break')}: <b>${all.filter(c=>ready(c,p.d)).length} / ${all.length}</b></p>${p.due.length?`<button class="btn secondary" id="alReview">${icon('listen')} ${t('Повторення на сьогодні','Due review')} · ${p.due.length}</button>`:''}<details><summary>${t('Маршрут навчання','Learning route')}</summary><ol class="al-route">${stages.map((s,i)=>`<li ${i===p.n?'aria-current="step"':''}><button type="button" class="al-route-open" data-al-stage="${i}" ${i===p.n?'aria-current="step"':''}>${esc(s.title[en()?1:0])} · ${s.cards.length} ${p.d.sessions[s.id]?'✓':''}</button></li>`).join('')}</ol></details><p class="hint">${t('Письмо та мікрофон можна пропустити. Пропуск не є помилкою й не означає, що слово засвоєне.','You can skip writing or microphone tasks. Skipping is neither a mistake nor evidence of mastery.')}</p>`);root.querySelectorAll('[data-al-stage]').forEach(button=>button.onclick=()=>{const stage=stages[Number(button.dataset.alStage)];begin(stage.cards,stage.id,true);root.scrollIntoView({block:'start',behavior:'auto'})});root.querySelector('#alStart').onclick=()=>start();const review=root.querySelector('#alReview');if(review)review.onclick=()=>begin(p.due.slice(0,6),null,false)}catch(e){shell(`<p role="alert">${t('Не вдалося прочитати прогрес. Дані не змінено.','Could not read progress. Your data was not changed.')}</p>`);console.error(e)}}
function begin(batch,stageId=null,intro=true,queue=null,journey=null){pause();session={batch:[...batch],stageId,journey,queue:queue||modes.flatMap(type=>shuffle(batch).map(c=>({c,type}))),index:0,answers:0,correct:0,skipped:0,results:[],locked:false,intro,finished:false};if(intro)study();else show()}
function start(){const p=plan();begin(p.selected,stages[p.n]?.id||null,true)}
function study(){const s=session;if(!s)return;if(s.journey?.final){shell(expeditionStory(s.journey)+`<div class="expedition-briefing-actions"><button class="btn primary" id="alContinue">${local(island().finalAction)}</button><button class="btn secondary" id="expeditionStudyBack">${t('← До мапи','← Map')}</button></div>`);root.querySelector('#alContinue').onclick=()=>{s.intro=false;show()};root.querySelector('#expeditionStudyBack').onclick=render;return}const st=stages.find(x=>x.id===s.stageId);shell(`${s.journey?expeditionStory(s.journey)+greetingBridge(s.journey,'welcome'):''}${s.journey?`<button type="button" class="btn secondary" id="expeditionStudyBack">${t('← До мапи','← Map')}</button>`:''}<div class="tag">${t('Знайомство','Meet the material')} · ${s.batch.length}</div><h2>${st?st.title[en()?1:0]:t('Повторюємо знайоме','Revisit familiar material')}</h2>${s.journey?`<p class="journey-goal"><b>${t('Після уроку ти зможеш:','After this lesson you can:')}</b> ${journeyLessons[s.journey.index].goal[en()?1:0]}</p><p>${t('Спочатку практика, потім тест із шести завдань. Мета — щонайменше 80%.','Practise first, then take a six-task test. Aim for at least 80%.')}</p>`:''}${st?'<p>'+esc(st.rule[en()?1:0])+'</p>':''}<button class="btn primary" id="alContinue">${s.journey?t('До практики','Start practice'):t('Перевір себе','Test yourself')}</button>${conversationPreview(s.journey)}<div class="course-grid al-study-grid">${s.batch.map(c=>`<article class="course-card al-word">${art(c)}<strong lang="de">${esc(c.de)}</strong>${listen(c)}<p>${esc(meaning(c))}</p></article>`).join('')}</div>`);const back=root.querySelector('#expeditionStudyBack');if(back)back.onclick=render;root.querySelector('#alContinue').onclick=()=>{s.intro=false;show()}}
function finish(){if(session?.journey){journeyFinish();return}pause();const s=session;s.finished=true;const d=load();if(s.stageId){d.sessions[s.stageId]={last:Date.now(),correct:s.correct,answers:s.answers,skipped:s.skipped};save(d)}const missed=s.results.filter(r=>!r.ok||r.skipped);shell(`<h1>${t('Порцію завершено','Batch complete')}</h1><p>${t('Правильно','Correct')}: ${s.correct} · ${t('Помилки','Mistakes')}: ${s.answers-s.correct} · ${t('Пропущено','Skipped')}: ${s.skipped}</p><div class="al-result-actions">${action('alAgain','repeat',t('Ще раз — усі п’ять етапів','Again — all five rounds'))}${action('alMistakes','book',t('Повторити помилки й пропущене','Repeat mistakes and skipped tasks'),!missed.length)}${action('alMore','arrow',t('Наступна вправа','Next exercise'))}</div><p class="hint">${t('Ще раз · Помилки й пропущене · Наступна вправа','Again · Mistakes and skipped · Next exercise')}</p><button class="btn secondary" id="alDone">${t('До мого плану','Back to my plan')}</button>`);root.querySelector('#alAgain').onclick=()=>begin(s.batch,s.stageId,false);root.querySelector('#alMistakes').onclick=()=>{const tasks=[...new Map(missed.map(r=>[r.c.id+':'+r.type,{c:r.c,type:r.type}])).values()];begin([...new Map(tasks.map(q=>[q.c.id,q.c])).values()],null,false,tasks)};root.querySelector('#alMore').onclick=start;root.querySelector('#alDone').onclick=render}
function action(id,glyph,title,disabled=false){const svg=glyph==='repeat'?'<path d="M4 10a8 8 0 1 1 1 8M4 4v6h6"/>':glyph==='arrow'?'<path d="M4 12h16m-7-7 7 7-7 7"/>':'<path d="M8 3h10v18H4V3h4m0 0v4h6V3M8 11h6M8 15h6M8 18h4"/>';return `<button type="button" class="al-icon-action" id="${id}" title="${esc(title)}" aria-label="${esc(title)}" ${disabled?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="#102B50" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${svg}</svg></button>`}

function show(){pause();const s=session;if(!s)return;if(s.index>=s.queue.length){finish();return}s.locked=false;s.helped=false;s.intro=false;const item=s.queue[s.index],c=item.c,type=item.type;s.options=item.dialoguePrompt?shuffle(s.batch.filter(z=>z.replyTo)):optionsFor(c);const title=item.dialoguePrompt?t('Відповідай співрозмовнику','Reply to the speaker'):label(type),isChoice=['ua','de','listen'].includes(type),prompt=item.dialoguePrompt||(type==='ua'?c.de:type==='listen'?'':meaning(c));
 shell(`${s.journey?`<div class="journey-session"><button type="button" class="btn secondary" id="journeyMapBack">${t('← Мапа','← Map')}</button><span>${s.journey.final?t('Випробування блоку','Block challenge'):expeditionStops[s.journey.index].name[en()?1:0]} · <b>${item.assessment?t('Тест','Test'):t('Практика','Practice')}</b></span></div>`:''}<div class="al-top"><span>${t('Завдання','Task')} ${s.journey?s.queue.slice(0,s.index+1).filter(q=>!!q.assessment===!!item.assessment).length:s.index+1} / ${s.journey?s.queue.filter(q=>!!q.assessment===!!item.assessment).length:s.queue.length}</span><button class="btn secondary" id="alExit">${t('Завершити','Finish')}</button></div>${teamTaskContext(s.journey,item)}${marketTaskContext(s.journey,item)}${residentTaskContext(s.journey,item)}<div class="al-rounds" aria-label="${esc(t('Етапи тренування','Training rounds'))}">${modes.map((m,i)=>`<span class="${m===type?'active':''}" title="${esc(label(m))}" aria-label="${esc(label(m))}" ${m===type?'aria-current="step"':''}>${icon(m)}</span>`).join('')}</div><h2>${title}</h2><article class="al-word course-card">${type==='listen'?`<button type="button" class="al-audio al-listen" id="alReplay" aria-label="${esc(t('Прослухати завдання','Play the task'))}">${icon('listen')}</button>`:`${art(c)}<strong ${type==='ua'?'lang="de"':''}>${esc(prompt)}</strong>${type==='ua'?listen(c):item.dialoguePrompt?`<button type="button" class="al-audio" id="alDialogueAudio" aria-label="${esc(t('Прослухати запитання','Listen to the question'))}">${icon('listen')}</button>`:''}`}</article>${isChoice?`<div class="al-options">${s.options.map((z,i)=>`<button type="button" class="btn secondary" data-al-option="${i}" ${type==='de'?'lang="de"':''}>${esc(type==='de'?z.de:meaning(z))}</button>`).join('')}</div>`:type==='write'?`<form id="alForm"><label for="alAnswer">${t('Німецька відповідь','German answer')}</label><input id="alAnswer" lang="de" autocomplete="off" autocapitalize="off" spellcheck="false"><div class="al-letters" lang="de" aria-label="${esc(t('Літери для відповіді','Answer letters'))}">${lettersFor(c).map(l=>`<button type="button" class="btn secondary" lang="de" title="${l===' '?t('Пробіл','Space'):l}" data-al-letter="${l}">${l===' '?'␣':l}</button>`).join('')}<button type="button" class="btn secondary" id="alBackspace" aria-label="${esc(t('Стерти літеру','Delete a letter'))}">⌫</button></div><button class="btn primary">${t('Перевірити','Check')}</button></form>`:`<button type="button" class="btn primary" id="alMic">${icon('speak')} ${t('Увімкнути мікрофон','Start microphone')}</button><p class="hint">${t('Перевіряємо розпізнані слова. Це не оцінка акценту.','Checks recognised words, not your accent.')}</p><div id="alHeard" role="status" aria-live="polite"></div><button class="btn secondary" id="alVoiceWrong" hidden>${t('Підтвердити помилку','Confirm mistake')}</button>`}<div role="status" aria-live="polite" id="alFeedback"></div><div class="al-bottom"><button type="button" class="btn secondary" id="alSkip">${t('Пропустити','Skip')} →</button><button type="button" class="btn primary" id="alNext" hidden>${t('Далі','Next')}</button></div>`);
 // A semantic image may contain a German caption; recall tasks must not reveal it.
 if(type!=='ua')root.querySelectorAll('.al-word [lang="de"],.al-word .phrase-art-cue,.al-word .course-art-caption').forEach(el=>el.remove());
 if(item.dialoguePrompt){root.querySelector('.al-word strong').lang='de';root.querySelector('#alDialogueAudio').onclick=()=>speak(item.dialoguePrompt);window.DEUTSCH_FLOW?.expose(item.dialoguePrompt,root)}
 const mapBack=root.querySelector('#journeyMapBack');if(mapBack)mapBack.onclick=render;root.querySelector('#alExit').onclick=()=>{cancel();render()};root.querySelector('#alSkip').onclick=skip;root.querySelector('#alNext').onclick=next;
 root.querySelectorAll('[data-al-option]').forEach(b=>b.onclick=()=>{const z=s.options[+b.dataset.alOption];b.dataset.answerState=z.id===c.id?'correct':'wrong';answer(type==='de'?z.de:meaning(z))});
 if(type==='write'){root.querySelector('#alForm').onsubmit=e=>{e.preventDefault();const value=root.querySelector('#alAnswer').value;if(value.trim())answer(value)};root.querySelectorAll('[data-al-letter]').forEach(b=>b.onclick=()=>{const input=root.querySelector('#alAnswer');input.setRangeText(b.dataset.alLetter,input.selectionStart??input.value.length,input.selectionEnd??input.value.length,'end');});root.querySelector('#alBackspace').onclick=()=>{const input=root.querySelector('#alAnswer'),end=input.selectionEnd??input.value.length,start=input.selectionStart??end;input.setRangeText('',start===end?Math.max(0,start-1):start,end,'end')}}
 if(type==='speak'){root.querySelector('#alMic').onclick=mic;if(!(window.SpeechRecognition||window.webkitSpeechRecognition)){root.querySelector('#alMic').disabled=true;root.querySelector('#alHeard').textContent=t('Цей браузер не підтримує розпізнавання. Можна пропустити вправу.','Speech recognition is unavailable in this browser. You can skip this task.')}}
 if(type==='listen'){root.querySelector('#alReplay').onclick=()=>play(c);window.DEUTSCH_FLOW?.expose(c.de,root)}
}
function next(){if(!session)return;session.index++;show()}
function skip(){const s=session;if(!s||s.locked||s.finished)return;const item=s.queue[s.index];s.results.push({...item,ok:false,skipped:true});s.skipped++;const d=load(),now=Date.now(),x=d.cards[item.c.id]||{step:0,success:0,bad:0,introduced:now};x.skills=x.skills||{};const skill=x.skills[item.type]||{step:0,ok:0,bad:0};skill.skipped=(skill.skipped||0)+1;skill.due=Math.min(skill.due||Infinity,now+600000);x.skills[item.type]=skill;x.due=Math.min(...Object.values(x.skills).map(v=>v.due));d.cards[item.c.id]=x;save(d);stopVoice();next()}
function answer(value,now=Date.now()){const s=session;if(!s||s.locked||s.intro||s.finished)return;const item=s.queue[s.index],c=item.c,type=item.type,expected=['ua','listen'].includes(type)?meaning(c):c.de;if(!String(value).trim())return;s.locked=true;stopVoice();const ok=norm(value)===norm(expected),d=load(),x=d.cards[c.id]||{step:0,success:0,bad:0,introduced:now};x.skills=x.skills||{};const previous=x.skills[type],skill={...(previous||{step:0,ok:0,bad:0})};skill.last=now;skill[ok?'ok':'bad']++;if(ok){if(!previous||previous.due<=now||previous.lastOutcome===false)skill.step=Math.min(7,(skill.step||0)+1);skill.due=previous&&previous.due>now&&previous.lastOutcome!==false?previous.due:now+[0,1,3,7,14,30,60,120][skill.step]*DAY;x.success++}else{skill.step=0;skill.due=now+600000;x.bad++}skill.lastOutcome=ok;x.skills[type]=skill;x.last=now;x.lastOutcome=ok;x.step=Math.min(...modes.slice(0,4).map(m=>x.skills[m]?.step||0));x.due=Math.min(...Object.values(x.skills).map(v=>v.due));d.cards[c.id]=x;save(d);window.DEUTSCH_PROGRESS?.record(ok,type,now);window.DEUTSCH_REVIEW?.recordLesson({de:c.de,ua:c.ua},ok,type,false);s.answers++;if(ok)s.correct++;s.results.push({...item,ok,skipped:false});root.querySelectorAll('[data-al-option]').forEach(b=>{if(+b.dataset.alOption===s.options.findIndex(z=>z.id===c.id))b.dataset.answerState='correct'});root.querySelectorAll('#alForm input,#alForm button,[data-al-option],#alMic,#alVoiceWrong,#alSkip').forEach(b=>b.disabled=true);const feedback=root.querySelector('#alFeedback');feedback.textContent=(ok?t('Правильно! ','Correct! '):t('Правильна відповідь: ','Correct answer: '))+c.de+' — '+meaning(c);feedback.className='feedback '+(ok?'good':'bad');tone(ok);root.querySelector('#alNext').hidden=ok;window.DEUTSCH_FLOW?.feedback(ok,c.de,next,()=>session===s&&!s.finished&&currentMode==='learning'&&s.queue[s.index]===item);if(!ok)root.querySelector('#alNext').focus()}
function mic(){const s=session;if(!s||s.locked||s.finished)return;stopVoice();window.DEUTSCH_FLOW?.pause();const C=window.SpeechRecognition||window.webkitSpeechRecognition;if(!C)return;const item=s.queue[s.index],run=voiceRun,valid=()=>session===s&&s.queue[s.index]===item&&currentMode==='learning'&&!s.locked&&run===voiceRun;const heard=root.querySelector('#alHeard'),confirm=root.querySelector('#alVoiceWrong');confirm.hidden=true;heard.textContent=t('Слухаю…','Listening…');let result=false;recognition=new C();recognition.lang='de-DE';recognition.interimResults=false;recognition.maxAlternatives=5;recognition.onresult=e=>{if(!valid())return;result=true;const choices=[...e.results[0]],said=choices[0]?.transcript||'';heard.replaceChildren();const transcript=document.createElement('div');transcript.textContent=t('Розпізнано: ','Recognised: ')+said;const confidence=document.createElement('div');confidence.className='al-confidence';const score=choices[0]?.confidence;confidence.textContent=Number.isFinite(score)&&score>0?t('Достовірність розпізнавання: ','Recognition confidence: ')+Math.round(Math.min(1,score)*100)+'%':t('Браузер не надав оцінку достовірності.','The browser did not provide a confidence score.');heard.append(transcript,confidence);const match=choices.find(v=>norm(v.transcript)===norm(item.c.de));if(match)answer(match.transcript);else{const help=document.createElement('p');help.textContent=t('Перевір розпізнавання: спробуй ще раз або підтвердь помилку.','Check the recognition: retry or confirm the mistake.');heard.append(help);confirm.hidden=false;confirm.onclick=()=>{if(valid())answer(said||'?')}}};recognition.onerror=()=>{if(valid())heard.textContent=t('Не вдалося розпізнати. Спробуй ще раз або пропусти.','Could not recognise speech. Retry or skip.')};recognition.onend=()=>{if(valid()&&!result)heard.textContent=t('Не почув відповіді. Можна повторити або пропустити.','No answer heard. Retry or skip.')};try{recognition.start()}catch{recognition.onerror()}}

